export function resolvePointer(doc, pointer) {
  if (pointer === '') return doc;
  let current = doc;
  for (const raw of pointer.split('/').slice(1)) {
    // Unescapes ~0 first, so ~01 wrongly becomes a separator.
    const token = raw.replace(/~0/g, '~').replace(/~1/g, '/');
    if (current === undefined || current === null) {
      throw new ReferenceError(`cannot resolve ${pointer}`);
    }
    current = current[token];
  }
  if (current === undefined) throw new ReferenceError(`cannot resolve ${pointer}`);
  return current;
}
